package aisdk

import (
	"encoding/json"
	"errors"
	"os"
	"strings"
	"testing"
	"unicode/utf8"
)

// The vectors are generated by conformance/scripts/generate-crypto-vectors.mjs, in
// TypeScript, because TypeScript is the reference. Go is made to match them, and the same
// files are asserted from the TS side too — a one-directional check cannot catch the
// failure that matters, which is Go accepting what the reference would reject.

type canonicalVector struct {
	Name          string          `json:"name"`
	Note          string          `json:"note,omitempty"`
	Input         json.RawMessage `json:"input"`
	CanonicalJSON string          `json:"canonicalJSON"`
	HashCanonical string          `json:"hashCanonical"`
}

type approvalVector struct {
	Name        string          `json:"name"`
	Note        string          `json:"note,omitempty"`
	Version     string          `json:"version"`
	Secret      string          `json:"secret"`
	ApprovalID  string          `json:"approvalId"`
	ToolCallID  string          `json:"toolCallId"`
	ToolName    string          `json:"toolName"`
	Input       json.RawMessage `json:"input"`
	Signature   string          `json:"signature"`
	Expect      string          `json:"expect"`
	PrincipalID string          `json:"principalId,omitempty"`
	ChatID      string          `json:"chatId,omitempty"`
	IssuedAt    int64           `json:"iat,omitempty"`
}

func loadVectors[T any](t *testing.T, path string) []T {
	t.Helper()
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v (regenerate with: cd conformance && node scripts/generate-crypto-vectors.mjs)", path, err)
	}
	var out []T
	if err := json.Unmarshal(raw, &out); err != nil {
		t.Fatalf("parse %s: %v", path, err)
	}
	if len(out) == 0 {
		t.Fatalf("%s is empty", path)
	}
	return out
}

// decodeInput turns a vector's raw JSON into the data model, which is the shape a decoded
// request body has.
func decodeInput(t *testing.T, raw json.RawMessage) any {
	t.Helper()
	var v any
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatalf("decode input: %v", err)
	}
	return v
}

// vectorsGoCannotReproduce are the two cases where Go's JSON decoder has already
// destroyed the input before any of our code runs: an unpaired surrogate escape becomes
// U+FFFD on ingest (measured), so Go never sees the value TypeScript canonicalized.
//
// This is a genuine, documented divergence rather than a bug to paper over. The
// substitution is lossy in a way that matters for a hash: "\uD800" and "\uD801" both
// become U+FFFD, so two distinct inputs would produce one digest. Go therefore refuses to
// canonicalize invalid UTF-8 instead of hashing a collapsed value.
var vectorsGoCannotReproduce = map[string]string{
	"lone-surrogate-key":   "Go's json.Unmarshal replaces the lone surrogate with U+FFFD on ingest",
	"lone-surrogate-value": "Go's json.Unmarshal replaces the lone surrogate with U+FFFD on ingest",
}

func TestCanonicalVectors_MatchTypeScript(t *testing.T) {
	vecs := loadVectors[canonicalVector](t, "testdata/canonical-vectors.json")

	var checked int
	for _, v := range vecs {
		t.Run(v.Name, func(t *testing.T) {
			if why, skip := vectorsGoCannotReproduce[v.Name]; skip {
				t.Skipf("documented divergence: %s", why)
			}

			input := decodeInput(t, v.Input)

			got, err := CanonicalJSON(input)
			if err != nil {
				t.Fatalf("CanonicalJSON: %v", err)
			}
			if got != v.CanonicalJSON {
				t.Errorf("canonicalJSON mismatch\n go: %s\n ts: %s", got, v.CanonicalJSON)
			}

			gotHash, err := HashCanonical(input)
			if err != nil {
				t.Fatalf("HashCanonical: %v", err)
			}
			if gotHash != v.HashCanonical {
				t.Errorf("hashCanonical mismatch\n go: %s\n ts: %s", gotHash, v.HashCanonical)
			}
			checked++
		})
	}
	if checked == 0 {
		t.Fatal("no canonical vectors were actually checked")
	}
}

// The vector that detects the sort divergence. Guarded explicitly so it cannot be
// removed or renamed without a failure: an emoji paired with a Latin-1 key agrees in both
// languages, so a fixture set without a non-BMP/U+E000-class pair would ship the bug.
func TestCanonicalVectors_SortDivergenceVectorIsPresent(t *testing.T) {
	vecs := loadVectors[canonicalVector](t, "testdata/canonical-vectors.json")

	var found bool
	for _, v := range vecs {
		if v.Name != "nonbmp-key-vs-private-use-key" {
			continue
		}
		found = true
		// UTF-16 order puts U+1F600 (first code unit 0xD83D) before U+E000; UTF-8 byte
		// order puts U+E000 (0xEE...) before U+1F600 (0xF0...). The expectation must
		// encode the former.
		iEmoji := strings.Index(v.CanonicalJSON, "\U0001F600")
		iPrivate := strings.Index(v.CanonicalJSON, "")
		if iEmoji < 0 || iPrivate < 0 {
			t.Fatalf("vector lost one of its keys: %s", v.CanonicalJSON)
		}
		if iEmoji > iPrivate {
			t.Errorf("expectation is in byte order, not UTF-16 order — it would pass "+
				"with sort.Strings and therefore detect nothing: %s", v.CanonicalJSON)
		}
	}
	if !found {
		t.Fatal("the non-BMP vs private-use-key vector is missing; without it the " +
			"key-sort divergence is untested")
	}
}

func TestApprovalVectors_MatchTypeScript(t *testing.T) {
	vecs := loadVectors[approvalVector](t, "testdata/approval-vectors.json")

	var accepts, rejects int
	for _, v := range vecs {
		t.Run(v.Name, func(t *testing.T) {
			binding := ApprovalBinding{
				ApprovalID:  v.ApprovalID,
				ToolCallID:  v.ToolCallID,
				ToolName:    v.ToolName,
				Input:       decodeInput(t, v.Input),
				PrincipalID: v.PrincipalID,
				ChatID:      v.ChatID,
				IssuedAt:    v.IssuedAt,
			}

			got := VerifyToolApproval([]byte(v.Secret), v.Signature, binding)
			want := v.Expect == "accept"
			if got != want {
				t.Errorf("verify = %v, want %v (%s)\n  note: %s", got, want, v.Expect, v.Note)
			}
			if want {
				accepts++
			} else {
				rejects++
			}
		})
	}

	// A vector file that drifted to all-accept or all-reject would still pass every
	// individual case while testing nothing.
	if accepts == 0 || rejects == 0 {
		t.Errorf("vectors must exercise both outcomes: %d accept, %d reject", accepts, rejects)
	}
}

// Signing must reproduce the reference signature, not merely verify it. A Go server whose
// signatures a TypeScript verifier rejects is just as broken as the reverse.
func TestSignToolApprovalV1_ReproducesTypeScriptSignature(t *testing.T) {
	vecs := loadVectors[approvalVector](t, "testdata/approval-vectors.json")

	var checked int
	for _, v := range vecs {
		if v.Version != "v1" || v.Expect != "accept" {
			continue
		}
		// Only the vectors whose signature is the canonical one for their binding; the
		// padded and standard-base64 variants are re-encodings of it.
		if strings.ContainsAny(v.Signature, "+/=") {
			continue
		}
		t.Run(v.Name, func(t *testing.T) {
			got, err := SignToolApprovalV1([]byte(v.Secret), ApprovalBinding{
				ApprovalID: v.ApprovalID, ToolCallID: v.ToolCallID,
				ToolName: v.ToolName, Input: decodeInput(t, v.Input),
			})
			if err != nil {
				t.Fatalf("SignToolApprovalV1: %v", err)
			}
			if got != v.Signature {
				t.Errorf("signature mismatch\n go: %s\n ts: %s", got, v.Signature)
			}
			checked++
		})
	}
	if checked == 0 {
		t.Fatal("no v1 signing vectors were checked")
	}
}

