// --- properties and traps not expressible as a single vector ---

// The depth budget must trip BEFORE hashing, since this is the first code to touch
// attacker JSON on the approval path.
func TestHashCanonical_RejectsPastDepthBudget(t *testing.T) {
	deep := any(1)
	for i := 0; i < CanonicalJSONMaxDepth+5; i++ {
		deep = map[string]any{"a": deep}
	}
	if _, err := HashCanonical(deep); err == nil {
		t.Fatal("deeply nested input was hashed instead of rejected")
	} else if !errors.Is(err, ErrCanonicalJSON) {
		t.Errorf("err = %v, want ErrCanonicalJSON", err)
	}

	// At the budget it must still succeed, or the limit is off by one and legitimate
	// payloads break.
	ok := any(1)
	for i := 0; i < CanonicalJSONMaxDepth-1; i++ {
		ok = map[string]any{"a": ok}
	}
	if _, err := HashCanonical(ok); err != nil {
		t.Errorf("input at the depth budget was rejected: %v", err)
	}
}

func TestCanonicalJSON_RejectsInvalidUTF8(t *testing.T) {
	// A WTF-8 encoded lone surrogate: what JSON.stringify emits verbatim and Go would
	// silently turn into U+FFFD.
	bad := string([]byte{0xED, 0xA0, 0x80})
	if utf8.ValidString(bad) {
		t.Fatal("test fixture is valid UTF-8; it cannot exercise the guard")
	}

	for _, tc := range []struct {
		name  string
		input any
	}{
		{"in a value", map[string]any{"k": bad}},
		{"in a key", map[string]any{bad: 1}},
		{"bare string", bad},
		{"inside an array", []any{bad}},
	} {
		if _, err := CanonicalJSON(tc.input); err == nil {
			t.Errorf("%s: invalid UTF-8 was canonicalized instead of rejected", tc.name)
		} else if !errors.Is(err, ErrCanonicalJSON) {
			t.Errorf("%s: err = %v, want ErrCanonicalJSON", tc.name, err)
		}
	}
}

// Two maps with the same entries in different insertion order must canonicalize
// identically — the whole point of the canonical form.
func TestCanonicalJSON_InsertionOrderIndependent(t *testing.T) {
	keys := []string{"z", "a", "m", "Ａ", "\U0001F600", "", "é", "0"}

	var first string
	for shift := range keys {
		obj := map[string]any{}
		for i := range keys {
			obj[keys[(i+shift)%len(keys)]] = i
		}
		got, err := CanonicalJSON(obj)
		if err != nil {
			t.Fatalf("CanonicalJSON: %v", err)
		}
		if shift == 0 {
			first = got
			continue
		}
		// Values differ per rotation, so compare the key sequence only.
		if gotKeys, wantKeys := extractKeys(got), extractKeys(first); gotKeys != wantKeys {
			t.Errorf("key order changed with insertion order\n got: %s\nwant: %s",
				gotKeys, wantKeys)
		}
	}
}

func extractKeys(canonical string) string {
	var keys []string
	for _, part := range strings.Split(strings.Trim(canonical, "{}"), ",") {
		if i := strings.LastIndex(part, ":"); i > 0 {
			keys = append(keys, part[:i])
		}
	}
	return strings.Join(keys, "|")
}

// Numbers must not depend on the Go type the caller happened to use.
func TestHashCanonical_NumericTypesAgree(t *testing.T) {
	want, err := HashCanonical(map[string]any{"n": float64(42)})
	if err != nil {
		t.Fatal(err)
	}
	for _, v := range []any{int(42), int64(42), float32(42), json.Number("42")} {
		got, err := HashCanonical(map[string]any{"n": v})
		if err != nil {
			t.Fatalf("%T: %v", v, err)
		}
		if got != want {
			t.Errorf("%T(42) hashed differently from float64(42): %s vs %s", v, got, want)
		}
	}
}

func TestDecodeBase64URLTolerant_MatchesReferenceLeniency(t *testing.T) {
	// The reference maps -→+ and _→/ then calls atob, which accepts padding, the
	// standard alphabet, and an unpadded final group.
	cases := []struct {
		in string
		ok bool
	}{
		{"AAAA", true},
		{"AAA=", true},  // padding — base64.RawURLEncoding would reject
		{"AA==", true},  // more padding
		{"a-_b", true},  // url alphabet
		{"a+/b", true},  // standard alphabet — RawURLEncoding would reject
		{"AAA", true},   // unpadded final group
		{"!!!!", false}, // invalid alphabet
		{"", false},     // empty
		{"====", false}, // padding only
	}
	for _, tc := range cases {
		_, ok := DecodeBase64URLTolerant(tc.in)
		if ok != tc.ok {
			t.Errorf("DecodeBase64URLTolerant(%q) ok = %v, want %v", tc.in, ok, tc.ok)
		}
	}
}

func TestVerifyToolApproval_NeverPanicsOnHostileSignature(t *testing.T) {
	b := ApprovalBinding{ApprovalID: "a", ToolCallID: "c", ToolName: "t", Input: nil}
	for _, sig := range []string{
		"", "=", "====", "!!!", strings.Repeat("A", 10000),
		"\x00\x01", "AAAA", "-_-_", "\n", " ",
	} {
		if VerifyToolApproval([]byte("secret"), sig, b) {
			t.Errorf("hostile signature %q verified", sig)
		}
	}
}

func TestCheckToolApproval_ErrorOrdering(t *testing.T) {
	secret := []byte("s3cret")
	b := ApprovalBinding{ApprovalID: "a1", ToolCallID: "c1", ToolName: "del", Input: nil}
	good, err := SignToolApprovalV2(secret, b)
	if err != nil {
		t.Fatal(err)
	}

	// A configured secret with no signature is reported as missing, distinctly from
	// invalid — the reference distinguishes them and so do audit logs.
	err = CheckToolApproval(secret, "", b)
	var sigErr *InvalidToolApprovalSignatureError
	if !errors.As(err, &sigErr) {
		t.Fatalf("missing signature: err = %v, want InvalidToolApprovalSignatureError", err)
	}
	if sigErr.Reason != ApprovalReasonMissingSignature {
		t.Errorf("reason = %q, want %q", sigErr.Reason, ApprovalReasonMissingSignature)
	}

	if err := CheckToolApproval(secret, "AAAA", b); !errors.As(err, &sigErr) ||
		sigErr.Reason != ApprovalReasonInvalidSignature {
		t.Errorf("bad signature: err = %v, want reason %q", err, ApprovalReasonInvalidSignature)
	}

	if err := CheckToolApproval(secret, good, b); err != nil {
		t.Errorf("valid signature rejected: %v", err)
	}

	// No secret means verification is off, matching the reference. Documented as a risk,
	// not a feature.
	if err := CheckToolApproval(nil, "", b); err != nil {
		t.Errorf("unconfigured secret should skip verification, got %v", err)
	}
}

// The error must not echo the attacker-supplied signature into a log.
func TestInvalidToolApprovalSignatureError_DoesNotEchoSignature(t *testing.T) {
	secret := []byte("s")
	hostile := "AAAA-hostile-marker-AAAA"
	err := CheckToolApproval(secret, hostile,
		ApprovalBinding{ApprovalID: "a1", ToolCallID: "c1", ToolName: "t"})
	if err == nil {
		t.Fatal("expected rejection")
	}
	if strings.Contains(err.Error(), "hostile-marker") {
		t.Errorf("error echoes the supplied signature: %v", err)
	}
}

// The legacy newline payload the reference still accepts must NOT verify here.
func TestVerifyToolApproval_RejectsLegacyNewlinePayload(t *testing.T) {
	vecs := loadVectors[approvalVector](t, "testdata/approval-vectors.json")
	var found bool
	for _, v := range vecs {
		if v.Name != "v1-legacy-newline-payload-must-not-verify" {
			continue
		}
		found = true
		if VerifyToolApproval([]byte(v.Secret), v.Signature, ApprovalBinding{
			ApprovalID: v.ApprovalID, ToolCallID: v.ToolCallID, ToolName: v.ToolName,
			Input: decodeInput(t, v.Input),
		}) {
			t.Error("a legacy newline-joined signature verified; ai-go deliberately " +
				"does not implement that fallback")
		}
	}
	if !found {
		t.Fatal("the legacy-newline vector is missing")
	}
}
